import type {ChatSession} from './session.js';

/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
export type Awaitable<T> = T | Promise<T>;

export interface BaseSession {
  sessionId: string;
  userId: string | number;
}

/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
export type SessionLookup<T extends BaseSession = ChatSession> =
  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};

/** What a conversation list needs of one session: never its entries, and never its credentials. */
export interface SessionSummary {
  sessionId: string;
  createdAt: Date;
  updatedAt: Date;
  entryCount: number;
}

/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
export interface SessionCursor {
  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
  updatedAt: Date | string | number;
  sessionId: string;
}

/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
export interface SessionListOptions {
  limit?: number;
  before?: SessionCursor;
}

export interface SessionCreateOptions {
  authHeaders?: ChatSession['authHeaders'];
  workspaceId?: string | number;
}

export interface SessionStore<T extends BaseSession = ChatSession> {
  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
  get(sessionId: string): Awaitable<T | undefined>;
  delete(sessionId: string): Awaitable<boolean>;
  count(): Awaitable<number>;
  clear(): Awaitable<void>;
  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
  evict?(sessionId: string): Awaitable<boolean>;
  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
  save?(session: T): Awaitable<void>;
  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
  latestFor?(userId: string | number): Awaitable<T | undefined>;
  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
}

import type {SessionEntry} from './session.js';
import type {SessionCursor} from './sessionStore.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: SessionCursor;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage;

export {ErrorCodes} from './session.js';

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

beforeEach(() => {
  logLines.length = 0;
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
  setLogger();
});

const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: userId}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') {
        connected = frame;
        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      frames.push(frame);
    });
  });
  return {connected, frames};
};

// A store with only the five required members, so listFor can be omitted, recorded or made to throw.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});

import type {IncomingMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  if (message.type === 'user_message') return validateUserMessage(message);
  if (message.type === 'ping') return validatePingMessage(message);
  if (message.type === 'list_sessions') return validateListSessionsMessage(message);
  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (!isValidOptionalLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const cursor = parseOptionalBefore(message.before);
  if (cursor === null) {
    return {valid: false, error: 'list_sessions before must have a valid updatedAt and sessionId'};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(message.limit !== undefined ? {limit: message.limit} : {}),
      ...(cursor !== undefined ? {before: cursor} : {}),
    },
  };
}

function isValidOptionalLimit(limit: unknown): limit is number | undefined {
  if (limit === undefined) return true;
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function parseOptionalBefore(before: unknown): SessionCursor | undefined | null {
  if (before === undefined) return undefined;
  if (typeof before !== 'object' || before === null) return null;

  const candidate = before as Record<string, unknown>;
  if (!isValidSessionId(candidate.sessionId) || !isValidCursorTimestamp(candidate.updatedAt)) {
    return null;
  }

  return {
    updatedAt: candidate.updatedAt,
    sessionId: candidate.sessionId,
  };
}

function isValidSessionId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
  return Number.isFinite(new Date(updatedAt).getTime());
}

import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions with optional limit and before, strips unknown fields, and rejects malformed options', () => {
    const beforeIso = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    const beforeEpoch = {updatedAt: 1767225600000, sessionId: 'a'.repeat(128)};
    const valid = {
      bare: validateMessage({type: 'list_sessions'}),
      withOptionsAndExtra: validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {...beforeIso, extra: 'ignored'},
        userId: 'other-user',
      }),
      withEpochCursor: validateMessage({type: 'list_sessions', limit: 25, before: beforeEpoch}),
    };
    const rejected = [
      validateMessage({type: 'list_sessions', limit: '10'}),
      validateMessage({type: 'list_sessions', limit: -1}),
      validateMessage({type: 'list_sessions', limit: 1.5}),
      validateMessage({type: 'list_sessions', before: null}),
      validateMessage({type: 'list_sessions', before: 'not-an-object'}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}),
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      }),
      validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}),
    ].map(outcome => outcome.valid);

    expect({valid, rejected}).toEqual({
      valid: {
        bare: {valid: true, data: {type: 'list_sessions'}},
        withOptionsAndExtra: {valid: true, data: {type: 'list_sessions', limit: 0, before: beforeIso}},
        withEpochCursor: {valid: true, data: {type: 'list_sessions', limit: 25, before: beforeEpoch}},
      },
      rejected: Array(9).fill(false),
    });
  });
});

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer, HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.

const servers: Array<{stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);
  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
  return {client, finished};
}

/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
export function announcedId(client: WebSocket): () => string {
  let sessionId = '';
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
  });
  return () => sessionId;
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}

import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {SessionResumeOptions} from './ws/sessionResume.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ConnectedMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what a reconnect is sent is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  resumeFailure?: string;
  index?: number;
  entry?: SessionEntry;
}

const NEVER_ISSUED = '0f1e2d3c-4b5a-4968-8776-655443322110';
const RESUME_ON: SessionResumeOptions = {enabled: true};
const LATEST_ON: SessionResumeOptions = {enabled: true, latest: true};
const HALF_ANSWER: SessionEntry = {
  role: 'assistant',
  content: 'half',
  timestamp: '2026-09-30T08:00:01.000Z',
  isStreaming: true,
};

// A tool's suppression lands while the answer is still open, as when a provider ends a tool round with no stop.
const suppressingMidAnswer: ChatOrchestrator = {
  processMessage: async () => 'before after',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'before'};
    yield {type: 'suppress_output'} as unknown as MessageChunk;
    yield {type: 'text', text: ' after'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

// Silenced for the whole file: the server logs every connection and close, and these tests read frames, not logs.
beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

afterAll(() => {
  setLogger();
});

// Each server sees its sockets close before it stops, so no close is logged after the logger above is restored.
afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
});

// The authenticated user is read per upgrade, so one test can reconnect as someone else.
const startEngine = async (
  store: SessionStore,
  resume?: SessionResumeOptions,
  orchestrator: ChatOrchestrator = answeringOrchestrator
) => {
  const auth = {userId: 'u1'};
  const connects: Array<{sessionId: string; resumed: boolean}> = [];
  const disconnected: string[] = [];
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: auth.userId}),
    sessionStore: store,
    orchestrator,
    resume,
    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
    onDisconnect: sessionId => void disconnected.push(sessionId),
  });
  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
  const firstServerClose = new Promise<void>(resolve => {
    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string, token = 't'): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
};

// One question answered and the socket closed, returning the id the connected frame announced.
const firstTurn = async (base: string): Promise<string> => {
  const client = open(base);
  let sessionId = '';
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
      if (frame.type === 'stream_end') resolve();
    });
  });
  client.close();
  await once(client, 'close');
  return sessionId;
};

// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
  const client = open(url, token);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      frames.push(frame);
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      if (frame.type === 'pong') resolve();
    });
  });
  return frames;
};

const upserts = (frames: Frame[]) =>
  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));

const shapeOf = (frames: Frame[]) => ({
  keys: Object.keys(frames[0]).sort(),
  resumed: frames[0].resumed,
  resumeFailure: frames[0].resumeFailure,
  types: frames.map(frame => frame.type),
});

const deferredRelease = () => {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release: () => release()};
};

// Each stored conversation holds one user entry, sent at the given time and reading as its own id.
const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string]>): InMemorySessionStore => {
  const store = new InMemorySessionStore();
  for (const [sessionId, userId, sentAt] of conversations) {
    const {entries} = store.create(sessionId, userId);
    entries.push({role: 'user', content: sessionId, timestamp: sentAt});
  }
  return store;
};

// A store with only the required members, so an optional one can be added, replaced or left out per test.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('resuming a conversation on reconnect', () => {
  it('with resume absent, answers a reconnect naming the first id with a new id and no replay', async () => {
    const {base} = await startEngine(new InMemorySessionStore());
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    expect({newId: frames[0].sessionId !== first, shape: shapeOf(frames)}).toEqual({
      newId: true,
      shape: {
        keys: ['examplePrompts', 'message', 'sessionId', 'type'],
        resumed: undefined,
        types: ['connected', 'pong'],
      },
    });
  });

  it('with resume on, answers the owner reconnecting with resumed true, entryCount 2 and both stored entries', async () => {
    const store = new InMemorySessionStore();
    const {base} = await startEngine(store, RESUME_ON);
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    const stored = JSON.parse(JSON.stringify((await store.get(first))?.entries)) as SessionEntry[];
    expect({connected: frames[0], replay: upserts(frames)}).toMatchObject({
      connected: {type: 'connected', sessionId: first, resumed: true, entryCount: 2},
      replay: [
        {index: 0, entry: stored[0]},
        {index: 1, entry: stored[1]},
      ],
    });
  });

  it('answers another user naming the id exactly as it answers an id that was never issued', async () => {
    const {auth, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
    const first = await firstTurn(base);
    auth.userId = 'u2';

    const otherUser = await connectAndSettle(`${base}?sessionId=${first}`);
    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);

    expect({fresh: otherUser[0].sessionId !== first, otherUser: shapeOf(otherUser)}).toEqual({
      fresh: true,
      otherUser: shapeOf(neverIssued),
    });
  });

  it('answers a never-issued id with resumed false, resumeFailure unknown, and no replay or error', async () => {
    const {base} = await startEngine(new InMemorySessionStore(), RESUME_ON);

    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);

    expect(shapeOf(frames)).toEqual({
      keys: ['examplePrompts', 'message', 'resumeFailure', 'resumed', 'sessionId', 'type'],
      resumed: false,
      resumeFailure: 'unknown',
      types: ['connected', 'pong'],
    });
  });

  it('never adopts a requested id as a key: one session, under the id the server minted', async () => {
    const store = new InMemorySessionStore();
    const {base} = await startEngine(store, RESUME_ON);

    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);

    expect({
      held: await store.count(),
      adopted: (await store.get(NEVER_ISSUED)) !== undefined,
      minted: (await store.get(frames[0].sessionId ?? '')) !== undefined,
    }).toEqual({held: 1, adopted: false, minted: true});
  });

  it('still calls onDisconnect with the session id when a socket closes under resume', async () => {
    const {disconnected, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);

    const first = await firstTurn(base);
    await eventually(() => disconnected.length > 0);

    expect(disconnected).toEqual([first]);
  });

  it('keeps the credentials of the socket that resumed a session when the socket it replaced closes', async () => {
    const store = new InMemorySessionStore();
    const {base, disconnected, firstServerClose} = await startEngine(store, RESUME_ON);
    const replaced = open(base, 'old');
    const [greeting] = (await once(replaced, 'message')) as [Buffer];
    const sessionId = (JSON.parse(String(greeting)) as Frame).sessionId ?? '';

    const frames = await connectAndSettle(`${base}?sessionId=${sessionId}`, 'new');
    replaced.close();
    await firstServerClose;

    const held = await store.get(sessionId);
    expect({resumed: frames[0].resumed, disconnected, authorization: held?.authHeaders?.authorization}).toEqual({
      resumed: true,
      disconnected: [sessionId],
      authorization: 'Bearer new',
    });
  });

  it('gives a session back the credentials of a socket still open when the socket that resumed it closes', async () => {
    const store = new InMemorySessionStore();
    const {base} = await startEngine(store, RESUME_ON);
    const first = open(base, 'first');
    const [greeting] = (await once(first, 'message')) as [Buffer];
    const sessionId = (JSON.parse(String(greeting)) as Frame).sessionId ?? '';
    const second = open(`${base}?sessionId=${sessionId}`, 'second');
    await once(second, 'message');
    const held = await store.get(sessionId);
    const whileBothOpen = held?.authHeaders?.authorization;

    second.close();
    await eventually(() => held?.authHeaders?.authorization !== whileBothOpen);

    expect({whileBothOpen, afterSecondCloses: held?.authHeaders?.authorization}).toEqual({
      whileBothOpen: 'Bearer second',
      afterSecondCloses: 'Bearer first',
    });
  });

  it('tells onConnect whether a connection started its session or resumed it', async () => {
    const {base, connects} = await startEngine(new InMemorySessionStore(), RESUME_ON);
    const first = await firstTurn(base);

    await connectAndSettle(`${base}?sessionId=${first}`);

    expect(connects).toEqual([
      {sessionId: first, resumed: false},
      {sessionId: first, resumed: true},
    ]);
  });

  it('resumes the id its store knows and starts fresh for one it does not', async () => {
    const store = new InMemorySessionStore();
    const known = await store.create('known', 'u1');
    known.entries.push({role: 'user', content: 'earlier', timestamp: '2026-09-30T08:00:00.000Z'});
    const {base} = await startEngine(store, RESUME_ON);

    const resumed = await connectAndSettle(`${base}?sessionId=known`);
    const fresh = await connectAndSettle(`${base}?sessionId=unknown`);

    expect({resumed: resumed[0], fresh: fresh[0]}).toMatchObject({
      resumed: {sessionId: 'known', resumed: true, entryCount: 1},
      fresh: {resumed: false},
    });
  });

  it('replays a suppressed entry as a skip, so the client never sees text a tool suppressed', async () => {
    const store = new InMemorySessionStore();
    const known = await store.create('known', 'u1');
    known.entries.push(
      {role: 'user', content: 'hello', timestamp: '2026-09-30T08:00:00.000Z'},
      {
        role: 'assistant',
        content: 'hidden',
