async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: import('../../types/sessionStore.js').SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);

  if (message.type === 'list_sessions') {
    if (!sessionStore?.listFor) {
      sendJson(ws, {type: 'session_list', sessions: []});
      return;
    }
    try {
      const summaries = await sessionStore.listFor(session.userId, {
        limit: message.limit,
        before: message.before
      });
      const sessions = summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : new Date(s.createdAt).toISOString(),
        updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : new Date(s.updatedAt).toISOString(),
        entryCount: s.entryCount
      }));
      sendJson(ws, {type: 'session_list', sessions});
    } catch (error) {
      log.error('ws', 'failed to list sessions', {
        userId: session.userId,
        error: error instanceof Error ? error.message : 'Unknown error'
      });
      sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
    }
  }
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

